    "pasos": [
      {
        "id": "paso-1",
        "titulo": "1. Resistencia de alterna (rac)",
        "pregunta": "Calcule la resistencia equivalente de alterna $r_{ac} = R_C \\parallel R_L$ (en kΩ).",
        "pistas": [
          "Pista 1: En señal, el capacitor de acoplamiento actúa como cortocircuito y $V_{CC}$ es masa dinámica.",
          "Pista 2: $r_{ac} = \\frac{R_C \\cdot R_L}{R_C + R_L} = \\frac{2.0 \\cdot 2.0}{2.0 + 2.0} = 1.0\\text{ k}\\Omega$."
        ],
        "explicacion": "En alterna, $R_C$ y $R_L$ quedan conectadas en paralelo: $r_{ac} = R_C \\parallel R_L = 2.0\\text{ k}\\Omega \\parallel 2.0\\text{ k}\\Omega = 1.0\\text{ k}\\Omega$.",
        "tipoRespuesta": "numerica",
        "unidad": "kΩ",
        "solucion": 1,
        "valorEsperado": 1,
        "tolerancia": 0.05,
        "simbolo": "r_{ac}",
        "explicacionPaso": "$r_{ac} = 2.0 \\parallel 2.0 = 1.0\\text{ k}\\Omega$."
      },
      {
        "id": "paso-2",
        "titulo": "2. Corriente de reposo óptima (ICQ)",
        "pregunta": "Determine la corriente de reposo óptima $I_{CQ,opt} = \\frac{V_{CC} - V_{CE,sat}}{R_{dc} + r_{ac}}$ (en mA).",
        "pistas": [
          "Pista 1: La resistencia estática de continua es $R_{dc} = R_C + R_E = 2.0 + 1.0 = 3.0\\text{ k}\\Omega$.",
          "Pista 2: La suma de resistencias es $R_{dc} + r_{ac} = 3.0 + 1.0 = 4.0\\text{ k}\\Omega$.",
          "Pista 3: $I_{CQ} = \\frac{15 - 0.2}{4.0\\text{ k}\\Omega} = \\frac{14.8}{4.0} = 3.70\\text{ mA}$."
        ],
        "explicacion": "Para igualar los recortes de corte ($I_{CQ} r_{ac}$) y saturación ($V_{CEQ} - V_{CE,sat}$): $I_{CQ,opt} = \\frac{V_{CC} - V_{CE,sat}}{(R_C + R_E) + r_{ac}} = \\frac{14.8\\text{ V}}{3.0\\text{ k}\\Omega + 1.0\\text{ k}\\Omega} = 3.70\\text{ mA}$.",
        "tipoRespuesta": "numerica",
        "unidad": "mA",
        "solucion": 3.7,
        "valorEsperado": 3.7,
        "tolerancia": 0.05,
        "simbolo": "I_{CQ}",
        "explicacionPaso": "$I_{CQ} = \\frac{15 - 0.2}{3.0 + 1.0} = 3.70\\text{ mA}$."
      },
      {
        "id": "paso-3",
        "titulo": "3. Tensión colector-emisor en reposo (VCEQ)",
        "pregunta": "Calcule la tensión continua $V_{CEQ} = V_{CC} - I_{CQ}(R_C + R_E)$ (en Volts).",
        "pistas": [
          "Pista 1: Caída de continua en $(R_C + R_E) = 3.70\\text{ mA} \\cdot 3.0\\text{ k}\\Omega = 11.10\\text{ V}$.",
          "Pista 2: $V_{CEQ} = 15 - 11.10 = 3.90\\text{ V}$."
        ],
        "explicacion": "$V_{CEQ} = 15\\text{ V} - 3.70\\text{ mA} \\cdot 3.0\\text{ k}\\Omega = 15 - 11.10 = 3.90\\text{ V}$. Observe que $V_{CEQ} - V_{CE,sat} = 3.90 - 0.2 = 3.70\\text{ V}$ y $I_{CQ} r_{ac} = 3.70\\text{ mA} \\cdot 1.0\\text{ k}\\Omega = 3.70\\text{ V}$, garantizando simetría perfecta de excursión.",
        "tipoRespuesta": "numerica",
        "unidad": "V",
        "solucion": 3.9,
        "valorEsperado": 3.9,
        "tolerancia": 0.05,
        "simbolo": "V_{CEQ}",
        "explicacionPaso": "$V_{CEQ} = 15 - 3.70 \\times 3.0 = 3.90\\text{ V}$."
      }
    ]
