        "unidad": "V/V",
        "solucion": -13.47,
        "valorEsperado": -13.47,
        "tolerancia": 0.05,
        "simbolo": "A_v",
        "explicacionPaso": "$A_v = -4.082 \\times 3.3 = -13.47\\text{ V/V}$."
